/** Replay the complete feed before selecting cells covered by the release ticket. */
export function publicationRows(source, catalog) {
  const window = source.window;
  if (!window || !["studio", "archive"].includes(window.service)) {
    throw new Error("publication window requires a studio or archive service");
  }
  name(window.tenant, "tenant");
  const from = day(window.from);
  const through = day(window.through);
  if (from > through) throw new Error("publication window is reversed");
  return projectCalendar(source, catalog).filter(row =>
    row.service === window.service && row.tenant === window.tenant &&
    row.day >= from && row.day <= through);
